int parseEstimate(const QString &text)
{
    const QStringList parts = text.trimmed().split(' ', Qt::SkipEmptyParts);
    if (parts.isEmpty())
        return -1;
    int total = 0;
    for (const QString &part : parts) {
        if (part.size() < 2)
            return -1;
        const QChar unit = part.at(part.size() - 1);
        bool ok = false;
        const int value = part.left(part.size() - 1).toInt(&ok);
        if (!ok || value < 0)
            return -1;
        if (unit == 'w')
            total += value * 5 * 24 * 60;
        else if (unit == 'd')
            total += value * 8 * 60;
        else if (unit == 'h')
            total += value * 60;
        else if (unit == 'm')
            total += value;
        else
            return -1;
    }
    return total;
}

QString formatEstimate(int minutes)
{
    if (minutes < 0)
        return {};
    QStringList out;
    const int weeks = minutes / (5 * 24 * 60);
    const int days = (minutes % (5 * 24 * 60)) / (8 * 60);
    const int hours = (minutes % (8 * 60)) / 60;
    const int mins = minutes % 60;
    if (weeks)
        out << QString::number(weeks) + "w";
    if (days)
        out << QString::number(days) + "d";
    if (hours)
        out << QString::number(hours) + "h";
    out << QString::number(mins) + "m";
    return out.join(' ');
}

