    check(parseEstimate("5x") == -1, "unknown unit -> -1");
    check(parseEstimate("d") == -1, "missing number -> -1");
    check(parseEstimate("-5m") == -1, "negative -> -1");
    check(parseEstimate("30m 1h") == 90, "any order");
    check(parseEstimate(" 1d 2h 30m ") == 630, "surrounding spaces");
    check(parseEstimate("1w") == 7200, "week = 5 days");
    check(parseEstimate("1w 1d") == 8160, "w+d");
    check(parseEstimate("10m") == 10, "plain minutes");

    // formatEstimate
    check(formatEstimate(0) == "0m", "0 -> 0m");
    check(formatEstimate(-5) == "", "negative -> empty");
    check(formatEstimate(2400) == "1w", "2400 -> 1w");
    check(formatEstimate(630) == "1d 2h 30m", "630");
    check(formatEstimate(480) == "1d", "480 -> 1d");
    check(formatEstimate(90) == "1h 30m", "90");
    check(formatEstimate(8 * 60 * 5 + 8 * 60 + 60) == "1w 1d 1h", "mixed all");

    // IssueModel: setData rules
    IssueModel model;
    model.addIssue({1, "a", 10, false});
    check(!model.addIssue({1, "dup", 5, false}), "duplicate id rejected");
    check(model.rowCount() == 1, "count unchanged after dup");
    QSignalSpy dc(&model, &QAbstractItemModel::dataChanged);
    check(!model.setData(model.index(0, 0), 10, IssueModel::EstimateRole), "unchanged estimate -> false");
    check(dc.count() == 0, "no dataChanged for unchanged");
    check(!model.setData(model.index(0, 0), -1, IssueModel::EstimateRole), "negative estimate -> false");
    check(model.setData(model.index(0, 0), 20, IssueModel::EstimateRole), "changed estimate -> true");
    check(dc.count() == 1, "one dataChanged");
    check(dc.at(0).at(2).at(0).toInt() == IssueModel::EstimateRole, "dataChanged names changed role");
    check(!model.setData(model.index(5, 0), 5, IssueModel::EstimateRole), "out-of-range row -> false");
    check(!model.setData(QModelIndex(), 5, IssueModel::EstimateRole), "invalid index -> false");
    check(!model.setData(model.index(0, 0), "x", Qt::DisplayRole), "DisplayRole not editable -> false");
    check(model.setData(model.index(0, 0), true, IssueModel::ClosedRole), "closed -> true");

    // BacklogSummary: emits once per change, never when unchanged
    IssueModel m2;
    m2.addIssue({1, "a", 10, false});
    m2.addIssue({2, "b", 20, true});
    BacklogSummary s(&m2);
    check(s.openMinutes() == 10, "initial open sum");
    QSignalSpy tc(&s, &BacklogSummary::totalChanged);
    m2.addIssue({3, "c", 30, false});
    check(s.openMinutes() == 40 && tc.count() == 1, "insert open -> emit once");
    m2.addIssue({4, "d", 30, true});
    check(s.openMinutes() == 40 && tc.count() == 1, "insert closed -> no emit");
    m2.removeIssue(3);
    check(s.openMinutes() == 10 && tc.count() == 2, "remove open -> emit");
    m2.removeIssue(4);
    check(tc.count() == 2, "remove closed -> no emit");
    m2.setData(m2.index(1, 0), false, IssueModel::ClosedRole);
    check(s.openMinutes() == 30 && tc.count() == 3, "reopen -> emit");
    m2.reset();
    check(s.openMinutes() == 0 && tc.count() == 4, "reset -> emit");
    m2.addIssue({1, "a", 10, false});
    check(tc.count() == 5, "re-add after reset -> emit");

    // destroy model -> openMinutes 0
    {
        IssueModel *m3 = new IssueModel;
        m3->addIssue({1, "a", 10, false});
        BacklogSummary s3(m3);
        check(s3.openMinutes() == 10, "s3 initial");
        delete m3;
        check(s3.openMinutes() == 0, "after destroy -> 0");
    }
    printf(fails ? "FAILURES: %d\n" : "ALL OK\n", fails);
    return fails;
}
EOF
