4	int parseEstimate(const QString &text)
5	{
6	    const QStringList parts = text.trimmed().split(' ', Qt::SkipEmptyParts);
7	    if (parts.isEmpty())
8	        return -1;
9	    int total = 0;
10	    for (const QString &part : parts) {
11	        if (part.size() < 2)
12	            return -1;
13	        const QChar unit = part.at(part.size() - 1);
14	        bool ok = false;
15	        const int value = part.left(part.size() - 1).toInt(&ok);
16	        if (!ok || value < 0)
17	            return -1;
18	        if (unit == 'w')
19	            total += value * 5 * 24 * 60;
20	        else if (unit == 'd')
21	            total += value * 8 * 60;
22	        else if (unit == 'h')
23	            total += value * 60;
24	        else if (unit == 'm')
25	            total += value;
26	        else
27	            return -1;
28	    }
29	    return total;
30	}
31	
32	QString formatEstimate(int minutes)
33	{
34	    if (minutes < 0)
35	        return {};
36	    QStringList out;
37	    const int weeks = minutes / (5 * 24 * 60);
38	    const int days = (minutes % (5 * 24 * 60)) / (8 * 60);
39	    const int hours = (minutes % (8 * 60)) / 60;
40	    const int mins = minutes % 60;
41	    if (weeks)
42	        out << QString::number(weeks) + "w";
43	    if (days)
44	        out << QString::number(days) + "d";
45	    if (hours)
46	        out << QString::number(hours) + "h";
47	    out << QString::number(mins) + "m";
48	    return out.join(' ');
49	}
